import{_ as t,o as e,c as o,Q as r}from"./chunks/framework.b67c47e6.js";const a="/assets/worktime-excel.830804ff.svg",b=JSON.parse('{"title":"Worktime Excel","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/worktime_excel/index.md","filePath":"guide/reports/worktime_excel/index.md","lastUpdated":1790354386000}'),s={name:"guide/reports/worktime_excel/index.md"},n=r('<h1 id="worktime-excel" tabindex="-1">Worktime Excel <a class="header-anchor" href="#worktime-excel" aria-label="Permalink to &quot;Worktime Excel&quot;">​</a></h1><p>The Worktime Excel generates a spreadsheet with the production time of each panel, taken from its checklist records. It is listed in <strong>Management files</strong>.</p><p><img src="'+a+'" alt="The Worktime Excel sheet, one row per assembly and station"></p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> Excel (.xlsx)</li><li><strong>Content:</strong> One sheet. Cell A1 holds the company name and C1 the project name (<em>all</em> for a company-wide report). Row 3 holds the column names, then one row per assembly (or per assembly and station):</li></ul><table><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>Assembly</td><td>Short panel ID (first 8 characters)</td></tr><tr><td>Phase, Batch, Order in batch</td><td>Where the panel sits in the project</td></tr><tr><td>Production Line</td><td>Line of the panel&#39;s batch</td></tr><tr><td>Production Station</td><td>Only in the per-station format</td></tr><tr><td>Design</td><td>Design name</td></tr><tr><td>Start datetime / Ready datetime</td><td>When the panel (or station) was started and finished, in the company&#39;s time zone. <em>Not started</em> / <em>Not ready</em> when there is no record.</td></tr><tr><td>Production time (mins)</td><td>Sum of the station times, from each station&#39;s start to its ready, counted in the company&#39;s working hours</td></tr><tr><td>Factory time (mins)</td><td>Working minutes from the panel&#39;s start to its ready</td></tr></tbody></table><p>Times are only filled in for panels that are ready; the others show 0. A <strong>Total time</strong> row at the bottom adds up both times.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This report is available both at <strong>project level</strong> and <strong>company level</strong>.</p><ul><li><strong>Project level</strong> — Includes every assembly of the project. The dates in the form are not used.</li><li><strong>Company level</strong> — Includes your company&#39;s assemblies whose scheduled production date falls between <strong>From</strong> and <strong>To</strong>. The dates start on the current week, Monday to Friday. Leave one empty for an open range.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Worktime Excel Format</strong></td><td>Choose how rows are organized (see below). Required.</td></tr><tr><td><strong>From</strong> / <strong>To</strong></td><td>Scheduled production date range (company-level reports).</td></tr></tbody></table><h2 id="format-options" tabindex="-1">Format Options <a class="header-anchor" href="#format-options" aria-label="Permalink to &quot;Format Options&quot;">​</a></h2><ul><li><strong>By constructible rows</strong> — One row per assembly, with its total times.</li><li><strong>By constructible-station rows</strong> — One row per assembly and station of its production line, showing the start, ready and time of each station separately. An assembly whose batch has no production line gets a single row.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <em>By constructible-station rows</em> format gives more detail about where time is spent in the production process, which is useful for identifying bottlenecks.</p></div><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Use this report for labor tracking, cost analysis, and production efficiency reviews.</p>',17),i=[n];function d(l,h,c,m,p,u){return e(),o("div",null,i)}const f=t(s,[["render",d]]);export{b as __pageData,f as default};
